mapper.insert:
insert into coupon_history (
    coupon_id, coupon_code, member_nickname, member_username,
    get_type, create_time, use_status, use_time, order_id, order_sn
) values (
    #{couponId}, #{couponCode}, #{memberNickname}, #{memberUsername},
    #{getType}, #{createTime}, #{useStatus}, #{useTime}, #{orderId}, #{orderSn}
)

mapper.select:
select ch.*, c.name as coupon_name, c.start_time, c.end_time from coupon_history ch left join coupon c on c.id = ch.coupon_id
and ch.coupon_id = #{couponId}
and ch.use_status = #{useStatus}
and ch.order_sn like concat('%', #{orderSn}, '%')
order by ch.create_time desc, ch.id desc

select ch.*, c.name as coupon_name, c.amount, c.min_point, c.use_type, c.platform, c.start_time, c.end_time, c.product_relation_json, c.product_category_relation_json from coupon_history ch inner join coupon c on c.id = ch.coupon_id where ch.member_username = #{username}
and ch.use_status = #{dto.useStatus}
order by ch.create_time desc, ch.id desc
